"use client";

import { useReducedMotion } from "motion/react";
import { type ComponentPropsWithoutRef, type PointerEvent, useCallback, useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a line that resolves from random characters to the real text. */
export type ScrambleTextProps = Omit<ComponentPropsWithoutRef<"span">, "children"> & {
  text: string;
  /**
   * `mount` runs when the line appears and again when `text` changes. `change`
   * runs only when `text` changes. `hover` runs each time a pointer enters.
   */
  trigger?: "mount" | "change" | "hover";
  /** Characters resolved each second. */
  speed?: number;
  /** The pool the random characters come from. Keep to glyphs the monospace face has. */
  characters?: string;
  /** Runs when the last character resolves. */
  onDone?: () => void;
};

// Milliseconds between two frames of noise. Faster than this reads as flicker.
const TICK = 40;
const POOL = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

/** Keeps the first `resolved` characters and every space, and draws the rest from the pool. */
function noiseAfter(text: string, resolved: number, pool: string) {
  return [...text]
    .slice(resolved)
    .map((char) => (/\s/.test(char) ? char : pool[Math.floor(Math.random() * pool.length)]))
    .join("");
}

/**
 * Resolves a line from random characters to the real text, left to right. The
 * monospace face gives every character the same width, so nothing shifts. The
 * server and the first paint show the real text. Screen readers get it once,
 * and with reduced motion the real text simply stays.
 */
export function ScrambleText({
  text,
  trigger = "mount",
  speed = 30,
  characters = POOL,
  onDone,
  className,
  onPointerEnter,
  ...spanProps
}: ScrambleTextProps) {
  const reduceMotion = useReducedMotion();
  // While a run is in flight this holds how many characters are real and the noise after them.
  const [frame, setFrame] = useState<{ resolved: number; noise: string } | null>(null);
  const timer = useRef<number | null>(null);
  const mounted = useRef(false);
  const done = useRef(onDone);

  useEffect(() => {
    done.current = onDone;
  }, [onDone]);

  const stop = useCallback(() => {
    if (timer.current !== null) window.clearInterval(timer.current);
    timer.current = null;
  }, []);

  const run = useCallback(() => {
    stop();
    const length = [...text].length;
    const pool = characters.length > 0 ? characters : POOL;
    let resolved = 0;
    timer.current = window.setInterval(() => {
      const whole = Math.floor(resolved);
      if (whole >= length) {
        stop();
        setFrame(null);
        done.current?.();
        return;
      }
      setFrame({ resolved: whole, noise: noiseAfter(text, whole, pool) });
      resolved += (speed * TICK) / 1000;
    }, TICK);
  }, [text, characters, speed, stop]);

  useEffect(() => {
    const first = !mounted.current;
    mounted.current = true;
    if (trigger === "hover" || (trigger === "change" && first)) return;
    if (reduceMotion) {
      // The text is already final, so the caller still hears that it is done.
      done.current?.();
      return;
    }
    run();
    return stop;
  }, [run, stop, trigger, reduceMotion]);

  // A hover run has no effect cleanup of its own, so stop it when the line goes away.
  useEffect(() => stop, [stop]);

  const enter = (event: PointerEvent<HTMLSpanElement>) => {
    onPointerEnter?.(event);
    // A finger has no hover; a tap must not start a run the person did not ask for.
    if (trigger === "hover" && !reduceMotion && event.pointerType !== "touch") run();
  };

  return (
    <span {...spanProps} className={cn("font-mono", className)} onPointerEnter={enter}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" data-scrambling={frame ? "true" : undefined} className="whitespace-pre-wrap">
        {frame ? (
          <>
            {[...text].slice(0, frame.resolved).join("")}
            <span className="text-muted-foreground">{frame.noise}</span>
          </>
        ) : (
          text
        )}
      </span>
    </span>
  );
}
